package ca.stewark.helioflux.ui.solaractivity
import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.unit.dp;import ca.stewark.helioflux.core.data.repository.RepositoryState;import ca.stewark.helioflux.core.model.FlareProbabilities
internal fun flareProbabilityLabels(state:RepositoryState<FlareProbabilities>):List<String>=when(state){is RepositoryState.Available->listOf("C ${state.data.c}%","M ${state.data.m}%","X ${state.data.x}%");is RepositoryState.Failure->state.retainedData?.let{listOf("C ${it.c}%","M ${it.m}%","X ${it.x}%")}?:listOf("Flare probabilities unavailable");RepositoryState.Loading->listOf("Loading flare probabilities");is RepositoryState.Empty->listOf("Flare probabilities unavailable")}
@Composable fun FlareProbabilityBadges(state:RepositoryState<FlareProbabilities>){Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){flareProbabilityLabels(state).forEach{label->AssistChip(onClick={},label={Text(label)})}}}
